#include <bits/stdc++.h>
using namespace std;

long long C[777][777];

int r, c;
long long total;
long long min_diff_val = (long long)1e18, min_z_val = -1;

void search_state(long long x, long long y, int v1, int v2) {
    long long diff = abs(x - y);
    if (min_diff_val <= 1 || diff - C[v1][r] * C[v2][r] >= min_diff_val) {
        return;
    }
    if (v1 == r - 1 && v2 == r - 1) {
        long long diff_now = abs(x - y);
        if (diff_now < min_diff_val) {
            min_diff_val = diff_now;
            min_z_val = x;
        }
        return;
    }
    if (v1 >= r) {
        long long inc1 = C[v1][r] - C[v1 - 1][r];
        long long sum2 = C[v2][r];
        search_state(x, y + inc1 * sum2, v1 - 1, v2);
    }
    if (v2 >= r) {
        long long sum1 = C[v1][r];
        long long inc2 = C[v2][r] - C[v2 - 1][r];
        search_state(x + sum1 * inc2, y, v1, v2 - 1);
    }
}

char s[12345];
int cntA[12345], cntB[12345];
map<long long, long long> memo_map5;

long long recurse4(long long x, long long y, int v1, int v2) {
    long long state_id = x * 10000 + v1 * 100 + v2;
    if (memo_map5.count(state_id)) {
        return memo_map5[state_id];
    }
    long long &res = memo_map5[state_id];
    long long diff = abs(x - y);
    if (diff - C[v1][r] * C[v2][r] > min_diff_val) {
        return res = 0;
    }
    if (v1 < r || v2 < r) {
        if (v1 >= cntA[v1 + v2] && v2 >= cntB[v1 + v2]) {
            int sum = v1 + v2;
            v1 -= cntA[sum];
            v2 -= cntB[sum];
            return res = C[v1 + v2][v1];
        }
        return res = 0;
    }
    res = 0;
    char ch_char = s[v1 + v2 - 1];
    if (ch_char != 'B') {
        long long delta1 = C[v1][r] - C[v1 - 1][r];
        long long sum2 = C[v2][r];
        res += recurse4(x, y + delta1 * sum2, v1 - 1, v2);
    }
    if (ch_char != 'A') {
        long long sum1 = C[v1][r];
        long long delta2 = C[v2][r] - C[v2 - 1][r];
        res += recurse4(x + sum1 * delta2, y, v1, v2 - 1);
    }
    return res;
}

int main() {
    scanf("%d %d", &r, &c);
    for (int i = 0; i <= 2 * (r + c); i++) {
        for (int j = 0; j <= 2 * (r + c); j++) {
            if (j == 0) C[i][j] = 1; else
            if (i == 0) C[i][j] = 0;
            else C[i][j] = C[i - 1][j] + C[i - 1][j - 1];
        }
    }
    total = C[r + c][r] * C[r + c][r];
    {
        long long x = 0, y = 0;
        int v1 = r + c, v2 = r + c;
        while (v1 >= r && v2 >= r) {
            if (x > y) {
                long long delta1 = C[v1][r] - C[v1 - 1][r];
                long long sum2 = C[v2][r];
                y += delta1 * sum2;
                v1--;
            } else {
                long long sum1 = C[v1][r];
                long long delta2 = C[v2][r] - C[v2 - 1][r];
                x += sum1 * delta2;
                v2--;
            }
        }
        min_diff_val = abs(x - y);
    }
    search_state(0, 0, r + c, r + c);
    scanf("%s", s);
    cntA[0] = cntB[0] = 0;
    for (int i = 0; i < 2 * (r + c); i++) {
        cntA[i + 1] = cntA[i] + (s[i] == 'A');
        cntB[i + 1] = cntB[i] + (s[i] == 'B');
    }
    long long answer5 = recurse4(0, 0, r + c, r + c);
    cout << answer5 << endl;
    return 0;
}
